import pptx

pptx_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/a3fbeb63-0e8c-4a11-bff6-0e3b484c3e9c.pptx"

terms = {"crab", "crabs", "lobster", "lobsters"}

def extract_slide_texts(pptx_path):
    prs = pptx.Presentation(pptx_path)
    slide_texts = []
    for i, slide in enumerate(prs.slides):
        text_parts = []
        for shape in slide.shapes:
            if hasattr(shape, "text"):
                text_parts.append(shape.text)
        # (Skipping notes for speed)
        slide_texts.append({"slide_number": i+1, "text": " ".join(text_parts)})
    return slide_texts

slide_texts = extract_slide_texts(pptx_path)
for s in slide_texts:
    print(f"Slide {s['slide_number']}: {s['text']}\n")

matched = []
for s in slide_texts:
    lower = s["text"].lower()
    if any(t in lower for t in terms):
        matched.append(s["slide_number"])
print("Preliminary crustacean-match slides:", matched)
print("Preliminary count:", len(matched))

This will give us a quick estimate; we can refine if necessary.
